import json
with open('apps/tfc/backend/seeds/silent_wake_baseline.json') as f:
    data = json.load(f)
content = data['content']

# Find all system_ids referenced in system_effects across all turns
referenced = set()
for turn in content.get('turns', []):
    for eff in turn.get('system_effects_on_start', []):
        referenced.add(eff.get('system_id'))

# Also check available_cards system_effects
for turn in content.get('turns', []):
    for card in turn.get('available_cards', []):
        for eff in card.get('system_effects', []):
            referenced.add(eff.get('system_id'))

print('Systems referenced in turn effects:')
for s in sorted(referenced):
    print(f'  {s}')

print()
print('All initial_system_states:')
for s in content.get('initial_system_states', []):
    print(f'  {s[\"system_id\"]}: {s[\"label\"]} (power={s[\"power_state\"]})')
"

