/* ── Two-Player Layout — Board Columns + CO Decision Bar ── */

@layer components {
  /* ── Board Columns (auto-fit grid for 2-player mode) ── */

  .board-columns {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
    gap: var(--spacing-md);
    padding: var(--spacing-md) var(--spacing-lg);
    flex: 1;
    min-height: 0;
    align-items: stretch;
  }

  /* Role cards inside board-columns fill the cell */
  .board-columns > .role-card {
    max-width: none;
    height: 100%;
  }

  /* ── CO Decision Bar ─────────────────────────────── */

  .co-decision-bar {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    padding: var(--spacing-md) var(--spacing-lg);
    border-top: 2px solid var(--color-success);
    background: color-mix(in oklch, var(--color-success) 5%, var(--color-card));
    flex-shrink: 0;
  }

  .co-decision-bar__options {
    display: flex;
    flex: 1;
    gap: var(--spacing-sm);
    flex-wrap: wrap;
  }

  .co-decision-bar__option {
    flex: 1 1 0;
    display: flex;
    flex-direction: column;
    gap: var(--spacing-2xs);
    padding: var(--spacing-sm) var(--spacing-md);
    border: 1px solid var(--color-border);
    border-radius: 2px;
    cursor: pointer;
    font-size: var(--font-size-sm);
    color: var(--color-foreground);
    transition:
      background 150ms ease,
      border-color 150ms ease;
  }

  .co-decision-bar__option:hover {
    background: var(--color-secondary);
  }

  .co-decision-bar__option--selected {
    background: var(--color-secondary);
    border-color: var(--color-success);
  }

  .co-decision-bar__option[data-recommended] {
    border-color: var(--color-primary);
    box-shadow: var(--glow-sm);
  }

  .co-decision-bar__option-label {
    font-weight: 500;
  }

  .co-decision-bar__rec-badge {
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    color: var(--color-primary);
    font-weight: 600;
  }

  .co-decision-bar__empty {
    flex: 1;
    text-align: center;
    color: var(--color-muted-foreground);
    font-family: var(--font-mono);
    font-size: var(--font-size-xs);
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  .co-decision-bar__intel {
    font-size: var(--font-size-sm);
    color: var(--color-muted-foreground);
    font-style: italic;
    padding-right: var(--spacing-md);
    border-right: 1px solid var(--color-border);
  }

  /* ── Readonly mirror mode ─────────────────────────── */

  .role-card__rec-check {
    color: var(--color-success);
    font-weight: 700;
    margin-left: auto;
  }

  .role-card__done--pending {
    font-style: italic;
  }

  /* ── Responsive ──────────────────────────────────── */

  @media (min-width: 1920px) {
    .board-columns {
      max-width: 1600px;
      margin-inline: auto;
    }
  }

  @media (max-width: 1024px) {
    .board-columns {
      grid-template-columns: 1fr;
    }
  }
}

