  1→import {
  2→  ChangeDetectionStrategy,
  3→  Component,
  4→  OnInit,
  5→  OnDestroy,
  6→  computed,
  7→  effect,
  8→  inject,
  9→  signal,
 10→} from "@angular/core";
 11→import { ButtonDirective } from "@aspect/ui";
 12→import { ActivatedRoute, Router } from "@angular/router";
 13→import { ClockDisplayComponent } from "../../shared/clock-display.component";
 14→import { PhaseBadgeComponent } from "../../shared/phase-badge.component";
 15→import { AmbientBackgroundComponent } from "../../shared/ambient-background.component";
 16→import { BriefingOverlayComponent } from "../../shared/briefing-overlay.component";
 17→import { CompletionOverlayComponent } from "../../shared/completion-overlay.component";
 18→import {
 19→  resolvePlayerRole,
 20→  submitRoleRecommendation,
 21→  submitDecision,
 22→} from "./player-decision-handlers";
 23→import { LogsDrawerComponent } from "../../shared/logs-drawer.component";
 24→import { StressBarComponent } from "../../shared/stress-bar.component";
 25→import { StressOverlayComponent } from "../../shared/stress-overlay.component";
 26→import { DomainService } from "../../core/domain.service";
 27→import { EngineApiService } from "../../core/engine-api.service";
 28→import { ExerciseWsService } from "../../core/exercise-ws.service";
 29→import { ExerciseStore } from "../../core/exercise.store";
 30→import { TickService } from "../../core/tick.service";
 31→import { DecisionApiService } from "../../core/decision-api.service";
 32→import { Subscription } from "rxjs";
 33→import { handlePlayerWsMessage } from "./player-ws-handler";
 34→import { RoleCardComponent } from "./role-card.component";
 35→import { SystemStatusBoardComponent } from "../../shared/system-status-board.component";
 36→import { WarfareDomainBoardComponent } from "../../shared/warfare-domain-board.component";
 37→import type { RoleCardSubmission } from "./role-card.component";
 38→import {
 39→  CoDecisionBarComponent,
 40→  type CoDecisionConfirmation,
 41→} from "./co-decision-bar.component";
 42→import { buildRoleCards } from "./role-card.types";
 43→
 44→@Component({
 45→  selector: "tfc-player-view",
 46→  changeDetection: ChangeDetectionStrategy.OnPush,
 47→  providers: [ExerciseStore, TickService],
 48→  imports: [
 49→    ClockDisplayComponent,
 50→    PhaseBadgeComponent,
 51→    AmbientBackgroundComponent,
 52→    BriefingOverlayComponent,
 53→    CompletionOverlayComponent,
 54→    LogsDrawerComponent,
 55→    StressBarComponent,
 56→    StressOverlayComponent,
 57→    ButtonDirective,
 58→    RoleCardComponent,
 59→    CoDecisionBarComponent,
 60→    SystemStatusBoardComponent,
 61→    WarfareDomainBoardComponent,
 62→  ],
 63→  templateUrl: "./player-view.html",
 64→})
 65→export class PlayerView implements OnInit, OnDestroy {
 66→  protected readonly store = inject(ExerciseStore);
 67→  protected readonly domain = inject(DomainService);
 68→  private readonly api = inject(EngineApiService);
 69→  private readonly decisionApi = inject(DecisionApiService);
 70→  protected readonly logsOpen = signal(false);
 71→  private readonly ws = inject(ExerciseWsService);
 72→  private readonly router = inject(Router);
 73→  private readonly route = inject(ActivatedRoute);
 74→  protected readonly roleLabel = signal("Advisor");
 75→  protected readonly beginningExercise = signal(false);
 76→  private readonly exerciseId = signal(1);
 77→  private readonly participantId = signal("");
 78→  private readonly tick = inject(TickService);
 79→  private snapshotLoaded = false;
 80→  private sub: Subscription | null = null;
 81→  private connSub: Subscription | null = null;
 82→
 83→  protected readonly stressEffectPreset = computed(
 84→    () => this.store.context()?.stress_effect_preset ?? "standard",
 85→  );
 86→
 87→  protected readonly activeDecisions = computed(() => {
 88→    const role = this.store.playerRole();
 89→    return this.store.openDecisions().filter((d) => {
 90→      if (!d.target_roles || d.target_roles.length === 0) return true;
 91→      if (
 92→        role === "all_roles" ||
 93→        role === "all_advisors" ||
 94→        role === "solo_player" ||
 95→        role === "decision_maker"
 96→      )
 97→        return true;
 98→      return d.target_roles.includes(role);
 99→    });
100→  });
101→
102→  protected readonly isMultiRole = computed(() => {
103→    const role = this.store.playerRole();
104→    return (
105→      role === "all_advisors" || role === "solo_player" || role === "all_roles"
106→    );
107→  });
108→
109→  protected readonly submittedRoles = signal<Set<string>>(new Set());
110→
111→  protected readonly currentTurnEvent = computed(() => {
112→    const decisions = this.activeDecisions();
113→    if (decisions.length === 0) return null;
114→    const decision = decisions[0];
115→    if (!decision.event_id) return null;
116→    return this.store.events().find((e) => e.id === decision.event_id) ?? null;
117→  });
118→
119→  protected readonly roleCards = computed(() => {
120→    const allRoles = this.store.context()?.roles ?? [];
121→    const event = this.currentTurnEvent();
122→    const decision = this.activeDecisions()[0] ?? null;
123→    const role = this.store.playerRole();
124→    const multiRole = this.isMultiRole();
125→    const playerRoleDef = allRoles.find((r) => r.id === role);
126→    const showDecisionMaker =
127→      role === "all_roles" ||
128→      role === "solo_player" ||
129→      role === "decision_maker" ||
130→      this.store.isPracticeMode() ||
131→      playerRoleDef?.player_type === "decision_maker";
132→    // Single-role players see only their own role card.
133→    // "decision_maker" URL param maps to the CO role (player_type === "decision_maker").
134→    let roles: typeof allRoles;
135→    if (multiRole) {
136→      roles = allRoles;
137→    } else if (role === "decision_maker") {
138→      roles = allRoles.filter((r) => r.player_type === "decision_maker");
139→    } else {
140→      roles = allRoles.filter((r) => r.id === role);
141→    }
142→    return buildRoleCards(
143→      roles,
144→      event,
145→      decision,
146→      this.submittedRoles(),
147→      showDecisionMaker,
148→      allRoles,
149→    );
150→  });
151→
152→  private _lastDecisionId: string | null = null;
153→  private readonly resetSubmittedRolesEffect = effect(() => {
154→    const id = this.activeDecisions()[0]?.id ?? null;
155→    // Only reset when the decision ID actually changes (not on every WS push)
156→    if (id && id !== this._lastDecisionId) {
157→      this._lastDecisionId = id;
158→      this.submittedRoles.set(new Set());
159→    }
160→  });
161→
162→  protected readonly advisorRoleCards = computed(() => {
163→    const allRoles = this.store.context()?.roles ?? [];
164→    const advisors = allRoles.filter((r) => r.player_type === "advisor");
165→    const activeCards = this.roleCards().filter(
166→      (c) => c.playerType === "advisor",
167→    );
168→    const activeMap = new Map(activeCards.map((c) => [c.roleId, c]));
169→    return advisors.map(
170→      (role) =>
171→        activeMap.get(role.id) ?? {
172→          roleId: role.id,
173→          roleLabel: role.label,
174→          playerType: "advisor" as const,
175→          intel: null,
176→          decision: null,
177→          status: "intel" as const,
178→          advisorRecs: [],
179→        },
180→    );
181→  });
182→
183→  protected readonly isDecisionMaker = computed(() => {
184→    const role = this.store.playerRole();
185→    const allRoles = this.store.context()?.roles ?? [];
186→    const playerRoleDef = allRoles.find((r) => r.id === role);
187→    return (
188→      role === "decision_maker" ||
189→      playerRoleDef?.player_type === "decision_maker"
190→    );
191→  });
192→
193→  protected readonly coRoleId = computed(() => {
194→    const allRoles = this.store.context()?.roles ?? [];
195→    return allRoles.find((r) => r.player_type === "decision_maker")?.id ?? null;
196→  });
197→
198→  protected readonly coIntel = computed(() => {
199→    const event = this.currentTurnEvent();
200→    const id = this.coRoleId();
201→    if (!event || !id) return null;
202→    return event.role_descriptions?.[id] ?? null;
203→  });
204→
205→  protected readonly advisorRoles = computed(() => {
206→    const allRoles = this.store.context()?.roles ?? [];
207→    return allRoles.filter((r) => r.player_type === "advisor");
208→  });
209→
210→  protected onCoDecisionConfirmed(confirmation: CoDecisionConfirmation): void {
211→    const decision = this.activeDecisions()[0];
212→    if (!decision) return;
213→    submitDecision(this.decisionApi, this.store, this.exerciseId(), decision, {
214→      selectedOptions: confirmation.selectedOptionIds,
215→      freeText: "",
216→      targetSystemSelections: confirmation.targetSystemSelections,
217→    });
218→  }
219→
220→  ngOnInit(): void {
221→    const params = this.route.snapshot.queryParams;
222→    const id = Number(params["exerciseId"] ?? 1);
223→    const pId = String(params["participantId"] ?? "");
224→    const role = String(params["role"] ?? "player");
225→    const gameMode = String(params["gameMode"] ?? "");
226→    this.exerciseId.set(id);
227→    this.participantId.set(pId);
228→    this.store.setParticipantId(pId);
229→    this.store.setPlayerRole(role);
230→    if (gameMode) {
231→      this.store.setGameMode(gameMode);
232→    }
233→    const practiceMode = params["practiceMode"] === "true";
234→    this.store.setPracticeMode(practiceMode);
235→    this.ws.connect(id, "player", pId || undefined);
236→    this.sub = this.ws.messages$.subscribe((msg) =>
237→      handlePlayerWsMessage(
238→        msg,
239→        this.store,
240→        () => this.onExerciseStopped(),
241→        this.ws,
242→      ),
243→    );
244→    this.loadSnapshot(id);
245→    this.decisionApi.getContext(id).subscribe({
246→      next: (ctx) =>
247→        resolvePlayerRole(ctx, role, gameMode, this.store, this.roleLabel),
248→      error: () => {},
249→    });
250→    this.decisionApi.getEngineDecisions(id).subscribe({
251→      next: (decisions) => this.store.applyDecisions(decisions),
252→      error: () => {},
253→    });
254→    this.connSub = this.ws.connected$.subscribe((connected) => {
255→      if (connected && this.snapshotLoaded) this.loadSnapshot(id);
256→    });
257→    this.tick.start(this.store);
258→  }
259→
260→  private loadSnapshot(exerciseId: number): void {
261→    this.api.snapshot(exerciseId).subscribe({
262→      next: (snap) => {
263→        this.snapshotLoaded = true;
264→        this.store.applySnapshot(snap);
265→      },
266→      error: () => this.store.setError("Failed to load snapshot"),
267→    });
268→  }
269→
270→  protected onBeginExercise(): void {
271→    this.beginningExercise.set(true);
272→    this.api.begin(this.exerciseId()).subscribe({
273→      next: (change) => {
274→        this.store.applyPhaseChange(change.phase);
275→        this.store.applyTimeUpdate(change.time);
276→        this.beginningExercise.set(false);
277→      },
278→      error: () => {
279→        this.store.setError("Failed to begin exercise");
280→        this.beginningExercise.set(false);
281→      },
282→    });
283→  }
284→
285→  protected onStop(): void {
286→    this.api.stop(this.exerciseId()).subscribe({
287→      next: () => this.onExerciseStopped(),
288→    });
289→  }
290→
291→  protected onExerciseStopped(): void {
292→    this.ws.disconnect();
293→    this.router.navigate(["/"]);
294→  }
295→
296→  ngOnDestroy(): void {
297→    this.tick.stop();
298→    this.ws.disconnect();
299→    this.sub?.unsubscribe();
300→    this.connSub?.unsubscribe();
301→  }
302→  protected onRoleCardSubmitted(submission: RoleCardSubmission): void {
303→    const decision = this.activeDecisions()[0];
304→    if (!decision) return;
305→    const role = this.store
306→      .context()
307→      ?.roles?.find((r) => r.id === submission.roleId);
308→    if (role?.player_type === "decision_maker") {
309→      submitDecision(
310→        this.decisionApi,
311→        this.store,
312→        this.exerciseId(),
313→        decision,
314→        submission,
315→      );
316→    } else {
317→      submitRoleRecommendation(
318→        this.decisionApi,
319→        this.exerciseId(),
320→        decision,
321→        this.participantId(),
322→        {
323→          roleId: submission.roleId,
324→          selectedOptions: submission.selectedOptions,
325→          freeText: submission.freeText,
326→        },
327→      );
328→    }
329→    const updated = new Set(this.submittedRoles());
330→    updated.add(submission.roleId);
331→    this.submittedRoles.set(updated);
332→  }
333→}
