 16→
 17→export interface CoDecisionConfirmation {
 18→  selectedOptionIds: string[];
 19→  targetSystemSelections: Record<string, string>;
 20→}
 21→
 22→@Component({
 23→  selector: "tfc-co-decision-bar",
 24→  changeDetection: ChangeDetectionStrategy.OnPush,
 25→  imports: [ButtonDirective],
 26→  template: `
 27→    @if (decision(); as d) {
 28→      <div class="co-decision-bar">
 29→        @if (coIntel()) {
 30→          <div class="co-decision-bar__intel">{{ coIntel() }}</div>
 31→        }
 32→        <div class="co-decision-bar__options">
 33→          @for (option of d.options; track option.id) {
 34→            <div
 35→              class="co-decision-bar__option"
 36→              [class.co-decision-bar__option--selected]="isSelected(option.id)"
 37→              [attr.data-recommended]="
 38→                getRecommenders(option.id).length > 0 ? '' : null
 39→              "
 40→              (click)="toggleOption(option.id)"
 41→            >
 42→              <span class="co-decision-bar__option-label">{{
 43→                option.label
 44→              }}</span>
 45→              @if (getRecommenders(option.id); as recs) {
 46→                @if (recs.length > 0) {
 47→                  <span class="co-decision-bar__rec-badge"
 48→                    >★ {{ recs.join(", ") }}</span
 49→                  >
 50→                }
 51→              }
 52→              @if (option.targets_system && isSelected(option.id)) {
 53→                <select
 54→                  class="role-card__system-picker"
 55→                  [value]="targetSystemSelections()[option.id] || ''"
 56→                  (change)="onSystemSelect(option.id, $event)"
 57→                  (click)="$event.stopPropagation()"
 58→                >
 59→                  <option value="">Select system...</option>
 60→                  @for (sys of systems(); track sys.system_id) {
 61→                    <option [value]="sys.system_id">{{ sys.label }}</option>
 62→                  }
 63→                </select>
 64→              }
 65→            </div>
 66→          }
 67→        </div>
 68→        <button
 69→          class="co-decision-bar__confirm"
 70→          uiButton
 71→          variant="default"
 72→          [disabled]="!canConfirm()"
 73→          (click)="onConfirm()"
 74→        >
 75→          Confirm
 76→        </button>
 77→      </div>
 78→    } @else {
 79→      <div class="co-decision-bar">
 80→        <div class="co-decision-bar__empty">Waiting for next decision...</div>
 81→      </div>
 82→    }
 83→  `,
 84→})
 85→export class CoDecisionBarComponent {
 86→  readonly decision = input<ActiveDecision | null>(null);
 87→  readonly advisorRoles = input<RoleDef[]>([]);
 88→  readonly systems = input<SystemSnapshot[]>([]);
 89→  readonly coIntel = input<string | null>(null);
 90→
 91→  readonly confirmed = output<CoDecisionConfirmation>();
 92→
 93→  readonly selectedOptionIds = signal<string[]>([]);
 94→  readonly targetSystemSelections = signal<Record<string, string>>({});
 95→
 96→  private readonly resetOnDecisionChange = effect(() => {
 97→    this.decision();
 98→    untracked(() => {
 99→      this.selectedOptionIds.set([]);
100→      this.targetSystemSelections.set({});
101→    });
102→  });
103→
104→  readonly canConfirm = computed(() => this.selectedOptionIds().length > 0);
105→
106→  protected isSelected(optionId: string): boolean {
107→    return this.selectedOptionIds().includes(optionId);
108→  }
109→
110→  protected getRecommenders(optionId: string): string[] {
111→    const d = this.decision();
112→    if (!d) return [];
113→    const roles = this.advisorRoles();
114→    const result: string[] = [];
115→    for (const [key, recOptionId] of Object.entries(d.recommendations)) {
116→      if (recOptionId === optionId) {
117→        const roleId = extractRecRoleId(key);
118→        const role = roles.find((r) => r.id === roleId);
119→        result.push(role?.label ?? roleId.toUpperCase());
120→      }
121→    }
122→    return result;
123→  }
124→
125→  protected toggleOption(optionId: string): void {
126→    const d = this.decision();
127→    if (!d) return;
128→    if (d.question_type === "single_choice") {
129→      this.selectedOptionIds.set([optionId]);
130→    } else {
131→      const current = this.selectedOptionIds();
132→      if (current.includes(optionId)) {
133→        this.selectedOptionIds.set(current.filter((id) => id !== optionId));
134→      } else {
135→        this.selectedOptionIds.set([...current, optionId]);
136→      }
137→    }
138→  }
139→
140→  protected onSystemSelect(optionId: string, event: Event): void {
141→    const select = event.target;
142→    if (!(select instanceof HTMLSelectElement)) return;
143→    this.targetSystemSelections.update((prev) => ({
144→      ...prev,
145→      [optionId]: select.value,
146→    }));
147→  }
148→
149→  protected onConfirm(): void {
150→    this.confirmed.emit({
151→      selectedOptionIds: this.selectedOptionIds(),
152→      targetSystemSelections: this.targetSystemSelections(),
153→    });
154→  }
155→}
