 24→@Component({
 25→  selector: "tfc-role-card",
 26→  changeDetection: ChangeDetectionStrategy.OnPush,
 27→  imports: [UpperCasePipe, BadgeComponent, ButtonDirective],
 28→  template: `
 29→    <div
 30→      class="role-card"
 31→      [class.role-card--intel]="card().status === 'intel'"
 32→      [class.role-card--active]="card().status === 'active'"
 33→      [class.role-card--done]="card().status === 'done'"
 34→    >
 35→      <!-- Header -->
 36→      <div class="role-card__header">
 37→        <span class="role-card__role-id">{{ card().roleId | uppercase }}</span>
 38→        <ui-badge
 39→          [variant]="card().status === 'active' ? 'default' : 'secondary'"
 40→        >
 41→          {{ badgeLabel() }}
 42→        </ui-badge>
 43→      </div>
 44→      <div class="role-card__role-label">{{ card().roleLabel }}</div>
 45→
 46→      <!-- Intel -->
 47→      @if (card().intel) {
 48→        <div class="role-card__intel">{{ card().intel }}</div>
 49→      } @else if (card().decision) {
 50→        <div class="role-card__intel role-card__intel--empty">
 51→          No role-specific intel this turn
 52→        </div>
 53→      }
 54→
 55→      <!-- Advisor Recs (CO card only) -->
 56→      @if (card().advisorRecs.length > 0) {
 57→        <div class="role-card__recs">
 58→          <div class="role-card__recs-title">Advisor Recommendations</div>
 59→          @for (rec of card().advisorRecs; track rec.roleId) {
 60→            <div
 61→              class="role-card__rec"
 62→              [class.role-card__rec--pending]="!rec.selection"
 63→            >
 64→              <span class="role-card__rec-role">{{ rec.roleLabel }}:</span>
 65→              @if (rec.selection) {
 66→                <span class="role-card__rec-selection">{{
 67→                  rec.selection
 68→                }}</span>
 69→              } @else {
 70→                <span class="role-card__rec-pending">pending...</span>
 71→              }
 72→            </div>
 73→          }
 74→        </div>
 75→      }
 76→
 77→      <!-- Decision Form (active only, interactive) -->
 78→      @if (card().decision && card().status === "active" && !readonly()) {
 79→        <div class="role-card__decision">
 80→          @if (
 81→            questionType() === "single_choice" ||
 82→            questionType() === "multi_choice"
 83→          ) {
 84→            @for (option of filteredOptions(); track option.id) {
 85→              <label
 86→                class="role-card__option"
 87→                [class.role-card__option--selected]="isSelected(option.id)"
 88→              >
 89→                <input
 90→                  [type]="
 91→                    questionType() === 'single_choice' ? 'radio' : 'checkbox'
 92→                  "
 93→                  [name]="'role-decision-' + card().roleId"
 94→                  [checked]="isSelected(option.id)"
 95→                  (change)="toggleOption(option)"
 96→                />
 97→                <span>{{ option.label }}</span>
 98→                @if (option.targets_system && isSelected(option.id)) {
 99→                  <select
100→                    class="role-card__system-picker"
101→                    [value]="targetSystemSelections()[option.id] || ''"
102→                    (change)="onSystemSelect(option.id, $event)"
103→                  >
104→                    <option value="">Select system...</option>
105→                    @for (sys of systems(); track sys.system_id) {
106→                      <option [value]="sys.system_id">{{ sys.label }}</option>
107→                    }
108→                  </select>
109→                }
110→              </label>
111→            }
112→          }
113→          @if (questionType() === "free_text") {
114→            <textarea
115→              class="role-card__textarea"
116→              [value]="freeText()"
117→              (input)="onTextInput($event)"
118→              placeholder="Enter your response..."
119→            ></textarea>
120→          }
121→          <div class="role-card__actions">
122→            <button
123→              uiButton
124→              variant="default"
125→              size="sm"
126→              (click)="onSubmit()"
127→              [disabled]="!canSubmit()"
128→            >
129→              Submit
130→            </button>
131→          </div>
132→        </div>
133→      }
134→
135→      <!-- Decision Mirror (readonly, CO view) -->
136→      @if (card().decision && card().status === "active" && readonly()) {
137→        <div class="role-card__decision">
138→          @for (option of filteredOptions(); track option.id) {
139→            <div
140→              class="role-card__option"
141→              [class.role-card__option--selected]="isRecommended(option.id)"
142→            >
143→              <span>{{ option.label }}</span>
144→              @if (isRecommended(option.id)) {
145→                <span class="role-card__rec-check">✓</span>
146→              }
147→            </div>
148→          }
149→          @if (pendingLabel()) {
150→            <div class="role-card__done role-card__done--pending">
151→              {{ pendingLabel() }}
152→            </div>
153→          }
154→        </div>
155→      }
156→
157→      <!-- Done State -->
158→      @if (card().status === "done") {
159→        <div class="role-card__done">Selected: {{ doneLabel() }}</div>
160→      }
161→    </div>
162→  `,
163→})
164→export class RoleCardComponent {
165→  readonly card = input.required<RoleCard>();
166→  readonly systems = input<SystemSnapshot[]>([]);
167→  readonly readonly = input(false);
168→  readonly submitted = output<RoleCardSubmission>();
169→
170→  readonly selectedOptions = signal<string[]>([]);
171→  readonly freeText = signal("");
172→  readonly targetSystemSelections = signal<Record<string, string>>({});
173→
174→  private readonly resetOnCardChange = effect(() => {
175→    this.card();
176→    untracked(() => {
177→      this.selectedOptions.set([]);
178→      this.freeText.set("");
179→      this.targetSystemSelections.set({});
180→    });
181→  });
182→
183→  readonly filteredOptions = computed<DecisionOption[]>(() => {
184→    const decision = this.card().decision;
185→    if (!decision) return [];
186→    const playerType = this.card().playerType;
187→    const roleId = this.card().roleId;
188→    if (playerType === "decision_maker") {
189→      return decision.options;
190→    }
191→    // advisor: COMMON options (no role) + own-role options
192→    return decision.options.filter((o) => !o.role || o.role === roleId);
193→  });
194→
195→  readonly badgeLabel = computed<string>(() => {
196→    const status = this.card().status;
197→    if (status === "intel") return "INTEL";
198→    if (status === "active") return "DECISION";
199→    return "DONE";
200→  });
201→
202→  readonly questionType = computed<string>(() => {
203→    return this.card().decision?.question_type ?? "free_text";
204→  });
205→
206→  readonly doneLabel = computed<string>(() => {
207→    const decision = this.card().decision;
208→    if (!decision) return "";
209→    const roleId = this.card().roleId;
210→    const recEntry = Object.entries(decision.recommendations).find(
211→      ([key]) => extractRecRoleId(key) === roleId,
212→    );
213→    const optionId = recEntry?.[1];
214→    if (!optionId) return "";
215→    return decision.options.find((o) => o.id === optionId)?.label ?? optionId;
216→  });
217→
218→  readonly pendingLabel = computed(() => {
219→    if (!this.readonly()) return null;
220→    const recs = this.card().decision?.recommendations ?? {};
221→    const roleId = this.card().roleId;
222→    const hasRec = Object.keys(recs).some(
223→      (key) => extractRecRoleId(key) === roleId,
224→    );
225→    return hasRec ? null : "pending...";
226→  });
227→
228→  protected isRecommended(optionId: string): boolean {
229→    const recs = this.card().decision?.recommendations ?? {};
230→    const roleId = this.card().roleId;
231→    return Object.entries(recs).some(
232→      ([key, val]) => extractRecRoleId(key) === roleId && val === optionId,
233→    );
234→  }
235→
236→  protected isSelected(optionId: string): boolean {
237→    return this.selectedOptions().includes(optionId);
238→  }
239→
240→  protected canSubmit(): boolean {
241→    if (this.questionType() === "free_text") {
242→      return this.freeText().trim().length > 0;
243→    }
244→    if (this.selectedOptions().length === 0) return false;
245→    const opts = this.filteredOptions();
246→    for (const optId of this.selectedOptions()) {
247→      const opt = opts.find((o) => o.id === optId);
248→      if (opt?.targets_system && !this.targetSystemSelections()[optId]) {
249→        return false;
250→      }
251→    }
252→    return true;
253→  }
254→
255→  protected toggleOption(option: DecisionOption): void {
256→    if (this.questionType() === "single_choice") {
257→      this.selectedOptions.set([option.id]);
258→    } else {
259→      const current = this.selectedOptions();
260→      if (current.includes(option.id)) {
261→        this.selectedOptions.set(current.filter((id) => id !== option.id));
262→      } else {
263→        this.selectedOptions.set([...current, option.id]);
264→      }
265→    }
266→  }
267→
268→  protected onSystemSelect(optionId: string, event: Event): void {
269→    const select = event.target;
270→    if (!(select instanceof HTMLSelectElement)) return;
271→    this.targetSystemSelections.update((prev) => ({
272→      ...prev,
273→      [optionId]: select.value,
274→    }));
275→  }
276→
277→  protected onTextInput(event: Event): void {
278→    if (!(event.target instanceof HTMLTextAreaElement)) return;
279→    const textarea = event.target;
280→    this.freeText.set(textarea.value);
281→  }
282→
283→  protected onSubmit(): void {
284→    this.submitted.emit({
285→      roleId: this.card().roleId,
286→      selectedOptions: this.selectedOptions(),
287→      freeText: this.freeText(),
288→      targetSystemSelections: this.targetSystemSelections(),
289→    });
290→  }
291→}
